'use strict';
(() => {
  const {types}=window.GameData, rounds=window.GameRounds;
  const $=s=>document.querySelector(s);
  const totalTypes=Object.keys(types).length,saveKey='gamebti-rounds-save-v2';
  let book=window.GameCollection.create(types,()=>localStorage);
  let session=null,result=null,screen='home',filter='unlocked',pendingGift=null,toastTimer,answerTimer=null;
  const mobile=matchMedia('(max-width:640px)');
  const sceneNames={team:'团队协作',relations:'朋友相处',discovery:'探索发现',building:'经营建造',challenge:'挑战难关',pace:'游玩节奏'};
  const whaleMark='<img class="whale-mark" src="assets/whale-mark.svg" width="24" height="18" alt="">';
  const lockIcon='<svg viewBox="0 0 40 48" fill="none" aria-hidden="true"><path d="M10 20v-8a10 10 0 0 1 20 0v8" stroke="currentColor" stroke-width="3"/><rect x="3" y="20" width="34" height="25" rx="5" stroke="currentColor" stroke-width="3"/><path d="M20 29v7" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg>';
  function character(code,className='card-icon'){const t=types[code],i=t.spriteIndex;return `<svg class="whale-sprite ${className}" viewBox="${i%4} ${Math.floor(i/4)} 1 1" aria-hidden="true"><image href="${t.sheet}" width="4" height="4" preserveAspectRatio="none"/></svg>`;}
  $('#whale-cast').innerHTML=character('G039','whale-companion whale-left')+character('G031','whale-main')+character('G042','whale-companion whale-right');
  function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
  function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
  function openDialog(d){d.showModal();document.body.classList.add('dialog-open');d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('dialog-open');},{once:true});}
  function showScreen(next){clearTimeout(answerTimer);answerTimer=null;screen=next;document.body.dataset.screen=next;['home','quiz','result'].forEach(id=>$('#'+id).hidden=id!==next);scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});if(next==='home')updateResume();}
  function save(){try{localStorage.setItem(saveKey,JSON.stringify(session));}catch{notify('进度没能保存下来，你可以继续答，但关掉页面后可能需要重新开始。');}}
  function readSave(){try{return rounds.restore(JSON.parse(localStorage.getItem(saveKey)));}catch{return null;}}
  function updateResume(){const s=readSave();$('#resume-button').hidden=!s;$('#resume-button').textContent=!s?'':s.stage==='quiz'?`继续第 ${s.rounds.length} 轮 · 第 ${rounds.active(s).index+1} / 12 题 →`:s.stage==='ended'?'查看本局获得的人格 →':`查看第 ${s.rounds.length} 轮结果，继续探索 →`;}
  function start(){
    const old=readSave();if(old&&old.stage!=='ended'&&!confirm('开始新的一局？当前这局进度会被替换，已解锁的图鉴会保留。'))return;
    closeDialogs();session=rounds.create();result=null;save();renderQuiz();showScreen('quiz');
  }
  function runTray(codes,interactive=false){
    const slots=Array.from({length:Math.max(3,codes.length+(interactive?0:1))},(_,i)=>{
      const code=codes[i],active=interactive&&code===result.code;
      const content=code?`${character(code,'run-avatar')}<span><small>第 ${i+1} 轮</small><b>${types[code].name}</b></span>`:`<span class="run-empty mono" aria-hidden="true">?</span><span><small>第 ${i+1} 轮</small><b>${!interactive&&i===session.rounds.length-1?'探索中':'待解锁'}</b></span>`;
      return code&&interactive?`<button class="run-slot card-${types[code].group}${active?' active':''}" data-result-type="${code}" aria-pressed="${active}">${content}</button>`:`<div class="run-slot${code?' earned card-'+types[code].group:(!interactive&&i===session.rounds.length-1?' current':'')}">${content}</div>`;
    });
    return `<div class="run-tray${interactive?' result-type-picker':''}" aria-label="本局人格卡">${slots.join('')}</div>`;
  }
  function renderQuiz(){
    const r=rounds.active(session),g=rounds.group(session),q=rounds.question(session),selected=r.answers[r.index];
    $('#quiz').innerHTML=`<div class="quiz-toolbar"><button class="back-link" data-action="home">← 回大厅</button><span class="quiz-phase">第 ${session.rounds.length} 轮 <b class="mono">${r.index+1} / 12</b></span></div><div class="progress-track" role="progressbar" aria-label="本轮答题进度" aria-valuemin="0" aria-valuemax="12" aria-valuenow="${r.index}"><div class="progress-fill" style="width:${r.index/12*100}%"></div></div>${runTray(rounds.results(session).map(item=>item.code))}<div class="quiz-question" data-theme="${g.id}"><span class="question-number mono" aria-hidden="true">${String(r.index+1).padStart(2,'0')}</span><span class="question-scene">${sceneNames[g.id]}</span><h2 class="question-title" id="question-title" tabindex="-1">${q.title}</h2><div class="answers round-answers ${q.options.every(option=>option.label.length<=30)?'answers-short':''}" role="group" aria-labelledby="question-title">${q.options.map((option,index)=>`<button class="answer ${selected===index?'selected':''}" data-answer="${index}" aria-pressed="${selected===index}"><span class="answer-key">${index+1}</span><span>${option.label}</span></button>`).join('')}</div></div><div class="quiz-bottom"><button class="quiz-prev" data-action="previous" ${r.index===0?'disabled':''}>← 上一题</button><span class="round-quiz-tip">选择后自动下一题<span class="keyboard-hint"> · 1–4 快捷键</span></span></div>`;
  }
  function refreshResult(){const found=rounds.results(session);result={code:found.at(-1)?.code,primaryIds:found.map(r=>r.code),ranked:found};}
  function chooseAnswer(index){
    if(answerTimer!==null||screen!=='quiz'||session?.stage!=='quiz')return;
    document.querySelectorAll('#quiz button').forEach(b=>b.disabled=true);
    const button=$(`[data-answer="${index}"]`);button.classList.add('selected');button.setAttribute('aria-pressed','true');
    rounds.answer(session,index);save();
    // 给选中状态留一点反馈时间，同时挡住连点穿透到下一题。
    answerTimer=setTimeout(()=>{answerTimer=null;if(session.stage==='result'){refreshResult();unlock(result.code,'self');renderResult(true);showScreen('result');}else{renderQuiz();scrollTo(0,0);$('#question-title').focus({preventScroll:true});}},180);
  }
  function continueRound(){if(!session||!rounds.canContinue(session))return;rounds.proceed(session);result=null;save();renderQuiz();showScreen('quiz');}
  function finishRun(){if(!session)return;rounds.finish(session);save();renderResult();showScreen('result');}
  function renderResult(reveal=false){
    if(session.stage==='ended'){
      $('#result').innerHTML=`<div class="completion-page"><div class="result-heading"><span class="completion-mark mono" aria-hidden="true">✓</span><span class="section-kicker mono">COLLECTION COMPLETE</span><h2>本局完成</h2><p>获得 ${result.primaryIds.length} 张人格卡</p></div><div class="completion-grid">${result.primaryIds.map(code=>{const t=types[code];return `<button class="completion-card card-${t.group}" data-type="${code}" aria-label="查看 ${t.name}"><span class="mono">${code}</span>${character(code,'completion-character')}<h3>${t.name}</h3><p>${t.trait}</p><span class="completion-view">查看人格 →</span></button>`;}).join('')}</div><div class="completion-actions"><button class="button button-dark" data-action="home">回大厅 →</button><button class="button button-outline" data-action="start">再开一局 ↻</button></div></div>`;
      return;
    }
    const t=types[result.code];
    const count=result.primaryIds.length,more=rounds.canContinue(session);
    const heading=`第 ${count} 轮结果`;
    const flow=`${more?`<button class="button ${count<3?'button-dark':'button-outline'}" data-action="continue">继续下一轮 →</button>`:''}${count>=3?`<button class="button button-dark" data-action="finish">完成本局 ✓</button>`:''}`;
    $('#result').innerHTML=`<div class="result-heading"><span class="section-kicker mono">PLAYER UNLOCKED</span><h2>${heading}</h2><p>已收集 ${count} 张${count<3?` · 再完成 ${3-count} 轮可结束`:''}</p></div>${runTray(result.primaryIds,true)}
      <div class="result-layout"><div class="identity-card card-${t.group}${reveal?' is-revealed':''}" id="identity-card"><div class="identity-top"><b class="identity-brand">gamebti ${whaleMark}</b><span class="mono">PLAYER ID CARD</span></div><div class="identity-code">${result.code}</div><h3>${t.name}</h3><span class="identity-en">${t.category}</span>${character(result.code,'identity-character')}<p class="identity-quote">“${t.quote}”</p><div class="identity-foot"><span>你的玩法，不只一种。</span><span class="mono">VOL. 003</span></div></div>
      <div class="result-detail"><div class="result-copy"><span class="section-kicker mono">PLAY STYLE</span><h3>${t.trait}</h3><p class="result-intro">${t.intro}</p><div class="result-habits"><h3>典型表现</h3><p>${t.example}</p></div></div><div class="round-flow">${flow}</div><div class="result-actions"><button class="button button-outline" data-action="download">保存图片 ↓</button><button class="button button-outline" data-action="share">分享 ↗</button><button class="text-link" data-action="collection">我的图鉴 →</button></div></div></div>`;
  }

  function lockedCard(n){return `<div class="player-card card-locked" aria-label="第 ${n} 格，未解锁"><div class="card-top"><span class="card-code">???</span><span class="card-number">NO.${String(n).padStart(2,'0')}</span></div><div class="locked-glyph">${lockIcon}</div><h3>尚未遇见</h3></div>`;}
  function card(code){const index=Object.keys(types).indexOf(code),t=types[code],source=book.source(code);if(!book.has(code))return lockedCard(index+1);return `<button class="player-card card-${t.group}" data-type="${code}" aria-label="了解 ${code} ${t.name}"><div class="card-top"><span class="card-code">${code}</span><span class="card-number">NO.${String(index+1).padStart(2,'0')}</span></div><div class="card-body"><div><h3>${t.name}</h3><span class="card-sub">${t.category}</span></div>${character(code)}</div><p class="card-quote">“${t.quote}”</p><span class="card-source">${source.self?(source.friend?'自己测出 · 也收到过':'自己测出的'):'朋友送来的'}</span><span class="card-arrow">↗</span></button>`;}
  function emptyCollection(){return `<div class="collection-empty"><div class="empty-lock">${lockIcon}</div><h3>${filter==='friend'?'还没收到搭子的人格卡':'还没有人格卡'}</h3><p>${filter==='friend'?'朋友给你发来人格链接后，点开就能把那张卡收进图鉴。':'你测出的人格会收在这里，朋友分享给你的卡片也能一起收藏。'}</p>${filter==='friend'?'':'<button class="button button-dark" data-action="start">开始测试 <span>↗</span></button>'}</div>`;}
  function renderCollection(){const codes=Object.keys(types).filter(code=>filter==='all'||(filter==='unlocked'?book.has(code):book.source(code)[filter]));$('#collection-grid').innerHTML=codes.length?codes.map(card).join(''):emptyCollection();const unlocked=book.codes();$('#collection-count').textContent=unlocked.length+'/'+totalTypes;$('#collection-progress-fill').style.width=unlocked.length/totalTypes*100+'%';$('#collection-filters').querySelectorAll('button').forEach(button=>{const kind=button.dataset.filter;button.classList.toggle('active',kind===filter);button.querySelector('span').textContent=kind==='all'?totalTypes:kind==='unlocked'?unlocked.length:unlocked.filter(code=>book.source(code)[kind]).length;});}
  function refreshCollection(){const codes=book.codes();$('#nav-unlocked').textContent=codes.length+'/'+totalTypes;$('#featured-players').innerHTML=codes.length?codes.slice(-4).map(card).join(''):emptyCollection();if($('#collection-dialog').open)renderCollection();}
  function unlock(code,source){const state=book.unlock(code,source);refreshCollection();if(!state.persisted)notify('这张卡已经解锁了，不过浏览器没能保存，关掉页面后可能会丢失。');return state;}
  function openCollection(code){closeDialogs();filter='unlocked';renderCollection();openDialog($('#collection-dialog'));if(code)previewType(code);}
  function previewType(code){if(!book.has(code))return;const t=types[code];$('#collection-grid .type-preview-detail')?.remove();$('#collection-grid').querySelectorAll('.player-card').forEach(card=>card.classList.toggle('selected',card.dataset.type===code));const detail=document.createElement('div');detail.className='type-preview-detail';detail.innerHTML=`<h3>${code} · ${t.name}</h3><p>${t.intro}</p><h4>典型表现</h4><p>${t.example}</p>`;const selected=$(`#collection-grid [data-type="${code}"]`),cards=[...$('#collection-grid').querySelectorAll('.player-card')],columns=Math.max(1,Math.round($('#collection-grid').clientWidth/(selected.offsetWidth+12))),index=cards.indexOf(selected),end=Math.min(Math.floor(index/columns)*columns+columns-1,cards.length-1);cards[end].after(detail);detail.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'nearest'});}
  function clearGiftHash(){const url=new URL(location.href),params=new URLSearchParams(url.hash.slice(1));if(params.has('meet')){params.delete('meet');url.hash=params.toString();history.replaceState(history.state,'',url);}}
  function handleGift(){const params=new URLSearchParams(location.hash.slice(1));if(!params.has('meet'))return;const code=window.GameCollection.parseGift(location.hash,types);if(!code){clearGiftHash();notify('链接无效，请朋友重新分享。');return;}pendingGift=code;closeDialogs();const t=types[code],known=book.has(code);$('#gift-content').innerHTML=`<p class="gift-eyebrow">${known?'这张卡你已经收过了，可以去图鉴里再看看。':'朋友给你发来了一张人格卡。'}</p><div class="gift-card card-${t.group}"><span class="gift-code mono">${code}</span>${character(code,'gift-character')}<h2 id="gift-title">${t.name}</h2><p>“${t.quote}”</p></div><button class="button button-dark" data-action="claim-gift">${known?'查看图鉴':'收藏人格'} <span>↓</span></button><button class="text-link" data-action="start">我也测一测 →</button>`;openDialog($('#gift-dialog'));}
  function claimGift(){if(!pendingGift)return;const code=pendingGift,{added}=unlock(code,'friend');$('#gift-dialog').close();clearGiftHash();pendingGift=null;openCollection(code);notify(added?'已收藏':'已在图鉴中');}
  function resultLink(code){return window.GameCollection.giftURL(location.href,code,types);}
  async function share(){if(!result?.code)return;const code=result.code,t=types[code],link=resultLink(code),message=`我的 GameBTI 人格：${t.name}。${t.quote}`;try{if(navigator.share&&location.protocol==='https:'){await navigator.share({title:'我的 GameBTI 人格',text:message,url:link});return;}if(navigator.clipboard&&isSecureContext){await navigator.clipboard.writeText(message+'\n'+link);notify('分享链接已复制');}else showCopyDialog(message+'\n'+link);}catch(error){if(error.name!=='AbortError')showCopyDialog(message+'\n'+link);}}
  function showCopyDialog(text){let d=$('#share-dialog');if(!d){d=document.createElement('dialog');d.id='share-dialog';d.className='about-dialog';document.body.append(d);}d.innerHTML='<button class="close-button" data-action="close" aria-label="关闭分享">×</button><h2>分享人格</h2><textarea aria-label="人格分享内容" class="share-copy" readonly></textarea><button class="button button-dark" data-action="copy-share">复制分享内容 ↓</button>';d.querySelector('textarea').value=text;openDialog(d);}
  async function copyShare(button){
    const field=$('#share-dialog').querySelector('textarea');button.disabled=true;
    try{
      let copied=false;
      if(isSecureContext&&navigator.clipboard){try{await navigator.clipboard.writeText(field.value);copied=true;}catch{}}
      if(!copied){field.focus();field.select();try{copied=!!document.execCommand?.('copy');}catch{}}
      if(copied)button.textContent='已复制 ✓';else{button.textContent='复制分享内容 ↓';notify('没能自动复制，文字已经帮你选好了，可以长按或按 Ctrl+C 复制。');}
    }finally{button.disabled=false;}
  }
  function previewCard(blob,code){let d=$('#card-preview-dialog');if(!d){d=document.createElement('dialog');d.id='card-preview-dialog';d.className='card-preview-dialog';document.body.append(d);}const t=types[code],url=URL.createObjectURL(blob),filename=`GameBTI-${code}-${t.name}.png`;d.innerHTML=`<div class="dialog-top"><h2>保存人格卡</h2><button class="close-button" data-action="close" aria-label="关闭人格卡预览">×</button></div><img class="card-preview-image" alt="${code} ${t.name} 人格卡"><p>也可以长按图片保存到相册。</p><div class="card-preview-actions"><a class="button button-dark" download>保存图片 ↓</a><button class="button button-outline" hidden>分享图片 ↗</button></div><button class="text-link card-preview-link" data-action="share">分享人格链接 →</button>`;d.querySelector('img').src=url;const link=d.querySelector('a');link.href=url;link.download=filename;const file=new File([blob],filename,{type:'image/png'}),button=d.querySelector('.button-outline');if(navigator.canShare?.({files:[file]})){button.hidden=false;button.addEventListener('click',async()=>{try{await navigator.share({files:[file],title:`GameBTI · ${t.name}`,text:resultLink(code)});}catch(error){if(error.name!=='AbortError')notify('可以长按图片保存，再把人格链接发给朋友。');}});}d.addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});openDialog(d);}
  const colors={team:'#dce7f0',self:'#e1d9ef',motivation:'#eee2ba',engagement:'#dbe7d4',interaction:'#f0d5c6',content:'#d5e9e8',completion:'#ebe4ce'};
  async function download(){
    if(!result?.code)return;const code=result.code,t=types[code],button=$('[data-action="download"]');button.disabled=true;button.textContent='正在生成…';
    try{if(document.fonts?.ready)await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1260;const ctx=canvas.getContext('2d');ctx.fillStyle=colors[t.group];ctx.fillRect(0,0,900,1260);ctx.fillStyle='#292d26';ctx.font='bold 35px Arial';ctx.fillText('gamebti',65,90);const mark=new Image();mark.src='assets/whale-mark.svg';await mark.decode();ctx.drawImage(mark,213,59,43,34);ctx.textAlign='right';ctx.font='18px monospace';ctx.fillText('PLAYER ID CARD · V2',835,86);ctx.strokeStyle='#292d2630';ctx.beginPath();ctx.moveTo(65,120);ctx.lineTo(835,120);ctx.stroke();ctx.textAlign='center';ctx.font='bold 94px Arial';ctx.fillText(code,450,265);ctx.font='bold 56px "Microsoft YaHei",sans-serif';ctx.fillText(t.name,450,350);ctx.font='22px "Microsoft YaHei",sans-serif';ctx.fillText(t.category,450,403);const image=new Image();image.src=t.sheet;await image.decode();const width=image.naturalWidth/4,height=image.naturalHeight/4;ctx.imageSmoothingEnabled=false;ctx.drawImage(image,t.spriteIndex%4*width,Math.floor(t.spriteIndex/4)*height,width,height,220,420,460,460);ctx.font='28px "Microsoft YaHei",sans-serif';ctx.fillText('“'+t.quote+'”',450,918);ctx.fillStyle='#5f6c55';ctx.font='24px "Microsoft YaHei",sans-serif';ctx.fillText(t.trait,450,982);ctx.fillStyle='#292d26';ctx.font='25px "Microsoft YaHei",sans-serif';ctx.fillText('你的玩法，不只一种。',450,1075);ctx.fillStyle='#6f7867';ctx.font='17px "Microsoft YaHei",sans-serif';ctx.fillText('仅供娱乐',450,1173);const blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(Error('empty')),'image/png'));if(mobile.matches)previewCard(blob,code);else{const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`GameBTI-${code}-${t.name}.png`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);notify('人格卡已经生成了，可以在浏览器的下载列表里找到。');}}catch{notify('图片生成没成功，可以先分享人格链接。');}finally{button.disabled=false;button.innerHTML='保存图片 <span>↓</span>';}
  }
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.answer!==undefined){chooseAnswer(Number(b.dataset.answer));return;}if(b.dataset.resultType){if(result?.primaryIds.includes(b.dataset.resultType)){result.code=b.dataset.resultType;renderResult();$('[data-result-type="'+result.code+'"]').focus({preventScroll:true});}return;}if(b.dataset.filter){filter=b.dataset.filter;renderCollection();return;}if(b.dataset.type){if(!$('#collection-dialog').open)openCollection(b.dataset.type);else previewType(b.dataset.type);return;}switch(b.dataset.action){case'start':start();break;case'continue':continueRound();break;case'finish':finishRun();break;case'previous':rounds.previous(session);save();renderQuiz();scrollTo(0,0);$('#question-title').focus({preventScroll:true});break;case'home':showScreen('home');break;case'collection':openCollection();break;case'about':openDialog($('#about-dialog'));break;case'close':b.closest('dialog').close();break;case'claim-gift':claimGift();break;case'share':share();break;case'copy-share':copyShare(b);break;case'download':download();break;}});
  document.querySelectorAll('.brand,.footer-brand').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();showScreen('home');}));
  $('#resume-button').addEventListener('click',()=>{const s=readSave();if(!s){updateResume();return;}session=s;if(s.stage==='quiz'){result=null;renderQuiz();showScreen('quiz');}else{refreshResult();result.primaryIds.forEach(code=>unlock(code,'self'));renderResult();showScreen('result');}});
  document.addEventListener('keydown',event=>{if(screen!=='quiz'||answerTimer!==null||document.querySelector('dialog[open]')||event.altKey||event.ctrlKey||event.metaKey||event.repeat)return;const index=Number(event.key)-1;if(Number.isInteger(index)&&index>=0&&index<4){event.preventDefault();document.querySelector(`[data-answer="${index}"]`)?.click();}});
  document.addEventListener('click',event=>{if(event.target.tagName==='DIALOG'){const box=event.target.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)event.target.close();}});
  $('#gift-dialog').addEventListener('close',()=>{if(!$('#gift-dialog').open){pendingGift=null;clearGiftHash();}});
  addEventListener('storage',event=>{if(event.key==='gamebti-collection-v2'){book=window.GameCollection.create(types,()=>localStorage);refreshCollection();}});
  const saved=readSave();if(saved){rounds.results(saved).forEach(({code})=>{if(!book.source(code).self)book.unlock(code,'self');});}
  refreshCollection();updateResume();handleGift();addEventListener('hashchange',handleGift);
})();
